 'use client';
import {useEffect,useState} from 'react';
export default function CertificateEmail({token}:{token:string}){const [configured,setConfigured]=useState(false);const [message,setMessage]=useState('Checking email availability…');const [email,setEmail]=useState('');const [consent,setConsent]=useState(false);const [busy,setBusy]=useState(false);useEffect(()=>{fetch('/api/archive/certificate-email/status',{cache:'no-store'}).then(async r=>{if(!r.ok)throw Error('Email service unavailable. Certificate download is still available.');const d=await r.json();setConfigured(d.configured);setMessage(d.configured?'':'Email is not configured. Use the certificate download.');}).catch(e=>setMessage(e.message));},[]);return <details className="source"><summary>Email my certificate (optional)</summary><p role="status">{message}</p>{configured&&<form onSubmit={async e=>{e.preventDefault();setBusy(true);try{const r=await fetch(`/api/archive/attempts/${token}/certificate-email`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({email,consent})});const d=await r.json();if(!r.ok)throw Error(typeof d.detail==='string'?d.detail:'Check the address and consent.');setMessage(d.message);setEmail('');setConsent(false);}catch(e){setMessage(e instanceof Error?e.message:'Email unavailable');}finally{setBusy(false);}}}><p>Your address is sent only to the configured mail service for this certificate. The archive stores consent and delivery status, not the address. Your chosen certificate name appears in the attachment.</p><label>Email address<input type="email" autoComplete="off" maxLength={254} value={email} required onChange={e=>setEmail(e.target.value)}/></label><label><input type="checkbox" required checked={consent} onChange={e=>setConsent(e.target.checked)}/> I request this one certificate by email and consent to use of this address for delivery.</label><button disabled={busy||!consent}>{busy?'Sending…':'Send requested certificate'}</button></form>}</details>;}
