'use client';
import Link from 'next/link';
import CertificateEmail from '../../../components/CertificateEmail';
import {use, useEffect, useState} from 'react';
type Attempt={attempt_id:string;title:string;questions:{prompt:string;options:string[]}[]};
type Result={score:number;total:number;feedback:{prompt:string;correct_option:string;explanation:string;source:{item_id:string;quote:string}}[]};
export default function Quiz({params}:{params:Promise<{id:string}>}){const {id}=use(params);const [attempt,setAttempt]=useState<Attempt|null>(null);const [answers,setAnswers]=useState<number[]>([]);const [result,setResult]=useState<Result|null>(null);const [message,setMessage]=useState('');const [busy,setBusy]=useState(false);const [name,setName]=useState('Archive visitor');const [certificate,setCertificate]=useState('');const [consent,setConsent]=useState(false);
 const [intro,setIntro]=useState<{description:string;evidence:{item_id:string;title:string;revision:number|null}[]}|null>(null);
 useEffect(()=>{const c=new AbortController();fetch('/api/archive/learning?kind=quiz',{cache:'no-store',signal:c.signal}).then(async r=>{if(r.ok){const rows=await r.json();setIntro(rows.find((e:{id:string})=>e.id===id)||null);}}).catch(()=>{});return()=>c.abort();},[id]);
 async function post(path:string,body:unknown={}){const r=await fetch(`/api/archive/${path}`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});const data=await r.json();if(!r.ok)throw Error(typeof data.detail==='string'?data.detail:'Request could not be completed');return data;}
 async function run(action:()=>Promise<void>){setBusy(true);setMessage('');try{await action();}catch(e){setMessage(e instanceof Error?e.message:'Request failed');}finally{setBusy(false);}}
 return <main className="page quiz-page"><Link href="/experience">← Learning activities</Link><h1>{attempt?.title||'Explore what you have learned'}</h1><p>Answers are checked on the server against a curator-reviewed key. A completion certificate is available after answering every question. This is a learning activity, not accreditation.</p>{!attempt&&intro&&<section className="quiz-introduction"><h2>Before you begin</h2><p>{intro.description}</p><h3>Supporting sources</h3><ul>{intro.evidence.map((e,i)=><li key={`${e.item_id}-${i}`}><Link className="text-link" href={`/archive/${e.item_id}${e.revision?`?revision=${e.revision}`:""}`}>{e.title}</Link></li>)}</ul></section>}{!attempt&&<button disabled={busy} onClick={()=>void run(async()=>{const a=await post(`learning/${id}/attempts`);setAttempt(a);setAnswers(a.questions.map(()=>-1));})}>Start reviewed quiz</button>}{attempt&&!result&&<form onSubmit={e=>{e.preventDefault();void run(async()=>setResult(await post(`attempts/${attempt.attempt_id}/submit`,{answers})));}}><div className="quiz-progress"><p role="status">{answers.filter(a=>a>=0).length} of {attempt.questions.length} answered</p><progress aria-label="Quiz completion" value={answers.filter(a=>a>=0).length} max={attempt.questions.length}/><p>{answers.some(a=>a<0)?`Answer ${answers.filter(a=>a<0).length} remaining question(s) before submitting.`:"All questions answered. Review your choices, then submit."}</p></div>{attempt.questions.map((q,i)=><fieldset className="quiz-question" key={i}><legend><span className="eyebrow">Question {i+1} of {attempt.questions.length}</span>{q.prompt}</legend>{q.options.map((option,n)=><label className="quiz-option" key={n}><input required type="radio" name={`question-${i}`} checked={answers[i]===n} onChange={()=>setAnswers(answers.map((a,j)=>j===i?n:a))}/>{option}</label>)}</fieldset>)}<button disabled={busy||answers.some(a=>a<0)}>Submit answers</button></form>}{result&&attempt&&<section className="quiz-results" aria-label="Quiz results"><button onClick={()=>{setAttempt(null);setResult(null);setAnswers([]);setCertificate('');setConsent(false);setName('Archive visitor');}}>Start a new attempt</button><h2>Completed · {result.score} / {result.total}</h2><p>Your result has been scored. Explore the explanations and supporting evidence below.</p><Link className="text-link" href="/leaderboard">View voluntary learning leaderboard →</Link>{result.feedback.map((f,i)=><article className="source" key={i}><h3>{f.prompt}</h3><p>Reviewed answer: {f.correct_option}</p><p>{f.explanation}</p><blockquote>{f.source.quote}</blockquote><Link href={`/archive/${f.source.item_id}`}>Read supporting source →</Link></article>)}<label>Name for certificate (optional; a pseudonym is welcome)<input maxLength={60} minLength={2} value={name} onChange={e=>setName(e.target.value)}/></label><p>Your chosen name appears on the certificate verification page. Leave “Archive visitor” for anonymity.</p><button disabled={busy} onClick={()=>void run(async()=>{const c=await post(`attempts/${attempt.attempt_id}/certificate`,{display_name:name});setCertificate(c.id);})}>{busy?"Preparing…":"Create completion certificate"}</button>{certificate&&<Link className="button" href={`/certificate/${certificate}`}>View and download certificate →</Link>}{certificate&&<CertificateEmail token={attempt.attempt_id}/>}<label className="quiz-option"><input type="checkbox" checked={consent} onChange={e=>setConsent(e.target.checked)}/> Optionally share my score on the public leaderboard under a generated pseudonym.</label><button disabled={busy||!consent} onClick={()=>void run(async()=>{const r=await post(`attempts/${attempt.attempt_id}/leaderboard`);setMessage(`Shared as ${r.alias}. No personal name is published on the leaderboard.`);})}>Share score voluntarily</button></section>}<p role="status">{busy?'Working…':message}</p></main>;}

